const $=(s,r=document)=>r.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults={site_config:[{id:'main',siteName:'Bui Loc',fullName:'Bùi Tấn Lộc',logoText:'Bui Loc',tagline:'Dự án, hoạt động và những điều đang được xây dựng.',intro:'Một không gian cá nhân để lưu lại các dự án, hoạt động, bài viết và hành trình theo cách gọn gàng, có chủ đích và không phô bày đời tư.',nowTitle:'Hiện tại',nowText:'Tập trung vào giáo dục, cộng đồng, sản phẩm số và việc xây dựng các hệ thống có thể vận hành lâu dài.',footerText:'© 2026 Bui Loc. Nội dung công khai được chọn lọc có chủ đích.'}],theme_config:[{id:'main',primary:'#1268F3',accent:'#00A6FF',background:'#F7F9FC',surface:'#FFFFFF',text:'#0B1220',mutedText:'#64748B',border:'#E2E8F0',radius:22,containerWidth:1180}],navigation:[{id:'home',label:'Trang chủ',url:'/',visible:true},{id:'about',label:'Giới thiệu',url:'/gioi-thieu',visible:true},{id:'projects',label:'Dự án',url:'/du-an',visible:true},{id:'activities',label:'Hoạt động',url:'/hoat-dong',visible:true},{id:'journey',label:'Hành trình',url:'/hanh-trinh',visible:true},{id:'posts',label:'Bài viết',url:'/bai-viet',visible:true},{id:'contact',label:'Liên hệ',url:'/lien-he',visible:true}],pages:[{id:'page-about',slug:'gioi-thieu',title:'Giới thiệu',summary:'Một phần giới thiệu vừa đủ về Bui Loc, tập trung vào công việc và những điều đang xây dựng.',status:'published',isPublished:true,content:'Website này không phải một bản lý lịch đầy đủ. Đây là nơi tập hợp những công việc, dự án, bài viết và dấu mốc được chủ động chọn để công khai.'},{id:'page-now',slug:'now',title:'Now',summary:'Những điều đang được tập trung ở thời điểm hiện tại.',status:'published',isPublished:true,content:'Tập trung vào giáo dục, cộng đồng, sản phẩm số và những hệ thống có thể vận hành lâu dài.'}],projects:[{id:'project-sfn',slug:'sky-first-network',title:'Sky First Network',summary:'Mạng lưới tập trung vào giáo dục, phát triển cộng đồng và người trẻ.',status:'published',isPublished:true,websiteUrl:'https://skyfirst.io.vn',content:'Một dự án đang được xây dựng theo hướng hệ sinh thái giáo dục và cộng đồng.'},{id:'project-sfec',slug:'sfec',title:'The Sky First English Club',summary:'Không gian học và hoạt động tiếng Anh thuộc hệ sinh thái Sky First.',status:'published',isPublished:true,websiteUrl:'https://sfec.skyfirst.io.vn'},{id:'project-nhn',slug:'nha-han-ngu',title:'Nhà Hán Ngữ',summary:'Dự án nội dung và học tập tiếng Trung.',status:'published',isPublished:true,websiteUrl:'https://nhahanngu.io.vn'},{id:'project-slc',slug:'slc',title:'SLC',summary:'Nền tảng lớp học trực tuyến đang được phát triển.',status:'published',isPublished:true,websiteUrl:'https://slc.skyfirst.io.vn'}],posts:[{id:'post-welcome',slug:'bat-dau-tu-mot-khong-gian-rieng',title:'Bắt đầu từ một không gian riêng',summary:'Vì sao website này được xây như một hệ thống có thể phát triển lâu dài.',status:'published',isPublished:true,category:'Ghi chép',content:'Một website cá nhân không nhất thiết phải kể quá nhiều về đời tư. Nó có thể là nơi ghi lại những thứ mình đang xây, những điều đã học và những nội dung muốn giữ lại lâu dài.'}],activities:[],journey:[]};
async function api(collection,id){try{let u='/api/cms?collection='+encodeURIComponent(collection)+(id?'&id='+encodeURIComponent(id):'');let r=await fetch(u);if(!r.ok)throw 0;let j=await r.json();return id?(j.item||null):(j.items||[])}catch{return id?(defaults[collection]||[]).find(x=>x.id===id)||null:(defaults[collection]||[])}}
function applyTheme(t){if(!t)return;let r=document.documentElement.style;for(let [k,v] of Object.entries({p:t.primary,a:t.accent,bg:t.background,s:t.surface,t:t.text,m:t.mutedText,b:t.border,r:(t.radius||22)+'px',w:(t.containerWidth||1180)+'px'}))r.setProperty('--'+k,v)}
function logo(){return `<svg viewBox="0 0 160 160" aria-hidden="true"><path d="M30 22h55c27 0 45 13 45 34 0 14-8 25-22 31l27 39h-30L82 92H59v34H30V22zm29 25v22h25c10 0 17-4 17-11s-7-11-17-11H59z" fill="currentColor"/><path d="M30 79h29v47h48l18 26H30V79z" fill="currentColor"/></svg>`}
function route(href){history.pushState({},'',href);render()} addEventListener('popstate',render);document.addEventListener('click',e=>{let a=e.target.closest('a[data-nav]');if(a){e.preventDefault();route(a.getAttribute('href'))}})
async function shell(content){let [site,nav,theme]=await Promise.all([api('site_config','main'),api('navigation'),api('theme_config','main')]);site=site||defaults.site_config[0];nav=nav.length?nav:defaults.navigation;theme=theme||defaults.theme_config[0];applyTheme(theme);$('#app').innerHTML=`<header class="header"><div class="shell head"><a data-nav href="/" class="brand">${logo()}<span>${esc(site.logoText||'Bui Loc')}</span></a><nav>${nav.filter(x=>x.visible!==false).map(x=>`<a data-nav href="${esc(x.url)}">${esc(x.label)}</a>`).join('')}</nav><a class="admin" href="/admin">Quản trị</a></div></header>${content}<footer class="footer"><div class="shell">${esc(site.footerText||'© 2026 Bui Loc')}</div></footer>`}
async function render(){let p=location.pathname;if(p.startsWith('/admin'))return admin();let site=await api('site_config','main')||defaults.site_config[0];if(p==='/'){let projects=await api('projects'),posts=await api('posts');return shell(`<main><section class="hero shell"><div class="eyebrow">Personal website</div><h1>Bui Loc.</h1><p class="lead">${esc(site.intro)}</p></section><section class="section shell"><div class="grid"><div class="card" style="grid-column:span 12"><span class="pill">${esc(site.nowTitle||'Hiện tại')}</span><h3 style="margin-top:16px">${esc(site.nowText)}</h3></div></div></section><section class="section shell"><h2>Những thứ đang xây</h2><div class="grid">${projects.slice(0,4).map(x=>`<a data-nav href="/du-an/${esc(x.slug)}" class="card project"><div class="eyebrow">Project</div><h3>${esc(x.title)}</h3><p>${esc(x.summary)}</p></a>`).join('')}</div></section><section class="section shell"><h2>Mới viết</h2><div class="grid">${posts.slice(0,3).map(x=>`<a data-nav href="/bai-viet/${esc(x.slug)}" class="card project"><h3>${esc(x.title)}</h3><p>${esc(x.summary)}</p></a>`).join('')}</div></section></main>`)}
 let map={'/du-an':['projects','Dự án'],'/bai-viet':['posts','Bài viết'],'/hoat-dong':['activities','Hoạt động'],'/hanh-trinh':['journey','Hành trình']};if(map[p]){let [c,t]=map[p],items=await api(c);return shell(`<main class="page shell"><div class="eyebrow">Bui Loc</div><h1>${t}</h1><div class="grid">${items.length?items.map(x=>`<a data-nav href="${p}/${esc(x.slug||x.id)}" class="card project"><h3>${esc(x.title)}</h3><p>${esc(x.summary||x.content||'')}</p></a>`).join(''):'<div class="card empty" style="grid-column:span 12">Nội dung sẽ được cập nhật từ CMS.</div>'}</div></main>`)}
 for(let [prefix,c] of [['/du-an/','projects'],['/bai-viet/','posts']])if(p.startsWith(prefix)){let slug=decodeURIComponent(p.slice(prefix.length)),items=await api(c),x=items.find(v=>v.slug===slug);if(x)return shell(`<main class="page shell article"><div class="eyebrow">${c==='posts'?'Bài viết':'Dự án'}</div><h1>${esc(x.title)}</h1><p class="lead">${esc(x.summary||'')}</p><div class="article"><p>${esc(x.content||'').replace(/\n/g,'</p><p>')}</p>${x.websiteUrl?`<p><a href="${esc(x.websiteUrl)}" target="_blank" rel="noopener" class="btn">Mở website</a></p>`:''}</div></main>`)}
 let slug=p.replace(/^\//,'');let pages=await api('pages'),x=pages.find(v=>v.slug===slug);if(x)return shell(`<main class="page shell article"><div class="eyebrow">Bui Loc</div><h1>${esc(x.title)}</h1><p class="lead">${esc(x.summary||'')}</p><div class="article"><p>${esc(x.content||'')}</p></div></main>`);if(p==='/lien-he')return shell(`<main class="page shell article"><div class="eyebrow">Bui Loc</div><h1>Kết nối</h1><p class="lead">Các kênh liên hệ công khai sẽ được quản lý từ CMS.</p></main>`);return shell(`<main class="page shell"><h1>404</h1><p class="lead">Không tìm thấy trang.</p></main>`)}
async function authState(){try{let r=await fetch('/api/admin-auth/profile');if(r.ok)return (await r.json()).user}catch{}return null}async function setupState(){try{let r=await fetch('/api/admin-auth/bootstrap');return r.ok?(await r.json()).needsSetup:false}catch{return false}}
async function seedCMS(){for(const [c,items] of Object.entries(defaults)){let live=await api(c);if(!live.length)for(const d of items)try{await fetch('/api/cms',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({collection:c,id:d.id,data:d})})}catch{}}}
async function admin(){let user=await authState();if(!user){let setup=await setupState();$('#app').innerHTML=`<main class="login"><form class="loginbox" id="login"><div class="brand">${logo()} Bui Loc CMS</div><h1>${setup?'Khởi tạo Owner':'Đăng nhập'}</h1><p class="muted">${setup?'Tạo tài khoản quản trị đầu tiên.':'Quản trị toàn bộ website tại đây.'}</p>${setup?'<div class="field"><label>Tên</label><input name="name" required></div>':''}<div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Mật khẩu</label><input type="password" name="password" required></div>${setup?'<div class="field"><label>Xác nhận mật khẩu</label><input type="password" name="confirmPassword" required></div>':''}<button class="btn" style="width:100%">${setup?'Khởi tạo':'Đăng nhập'}</button><div id="err"></div></form></main>`;$('#login').onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.currentTarget));let r=await fetch('/api/admin-auth/'+(setup?'bootstrap':'login'),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)}),j=await r.json();if(!r.ok)$('#err').innerHTML=`<div class="notice danger">${esc(j.error)}</div>`;else admin()};return}
 await seedCMS(); let sections=['Dashboard','Trang','Bài viết','Dự án','Hoạt động','Hành trình','Media','Menu','Giao diện','SEO & hệ thống'];$('#app').innerHTML=`<div class="adminapp"><aside class="side"><div class="brand">${logo()} Bui Loc</div>${sections.map((x,i)=>`<button data-sec="${i}" class="${i===0?'on':''}">${x}</button>`).join('')}<hr style="border-color:#203047"><button id="view">↗ Xem website</button><button id="logout">Đăng xuất</button></aside><main class="main"><div class="topbar"><div><h1 style="margin:0">Bui Loc CMS</h1><div class="muted">${esc(user.name)} · ${esc(user.role)}</div></div></div><div id="work"></div></main></div>`;document.querySelectorAll('[data-sec]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-sec]').forEach(x=>x.classList.remove('on'));b.classList.add('on');adminSection(+b.dataset.sec)});$('#view').onclick=()=>location.href='/';$('#logout').onclick=async()=>{await fetch('/api/admin-auth/logout',{method:'POST'});admin()};adminSection(0)}
const colBySec={1:'pages',2:'posts',3:'projects',4:'activities',5:'journey'};async function adminSection(i){let w=$('#work');if(i===0){let h;try{h=await (await fetch('/api/system/health')).json()}catch{}w.innerHTML=`<div class="grid"><div class="panel" style="grid-column:span 8"><h2>Dashboard</h2><p>Quản trị nội dung, giao diện, menu và media mà không cần sửa source.</p></div><div class="panel" style="grid-column:span 4"><h3>Hệ thống</h3><p>D1: ${h?.d1?'✓':'—'} &nbsp; R2: ${h?.r2?'✓':'—'}</p></div></div>`;return}if(colBySec[i])return collectionUI(colBySec[i]);if(i===6)return mediaUI();if(i===7)return collectionUI('navigation');if(i===8)return themeUI();if(i===9){w.innerHTML=`<div class="panel"><h2>SEO & hệ thống</h2><p>Domain: <b>builoc.name.vn</b></p><p>D1 và R2 được kết nối bằng binding; nội dung không cần chỉnh trực tiếp trong Cloudflare.</p><button class="btn" onclick="location.href='/sitemap.xml'">Xem sitemap</button></div>`}}
async function collectionUI(c){let items=await api(c),w=$('#work');w.innerHTML=`<div class="panel"><div class="row" style="justify-content:space-between"><div><h2 style="margin:0">${c}</h2><div class="muted">${items.length} mục</div></div><button class="btn" id="new">+ Thêm mới</button></div></div><div class="panel"><table class="table"><thead><tr><th>Tiêu đề</th><th>Slug / URL</th><th>Trạng thái</th><th></th></tr></thead><tbody>${items.map(x=>`<tr><td><b>${esc(x.title||x.label||x.id)}</b></td><td>${esc(x.slug||x.url||'')}</td><td>${esc(x.status||'—')}</td><td><button class="btn ghost edit" data-id="${esc(x.id)}">Sửa</button></td></tr>`).join('')}</tbody></table></div>`;$('#new').onclick=()=>editDoc(c,null);document.querySelectorAll('.edit').forEach(b=>b.onclick=()=>editDoc(c,b.dataset.id))}
async function editDoc(c,id){let x=id?await api(c,id):null;x=x||{id:crypto.randomUUID(),title:'',slug:'',summary:'',content:'',status:'draft',isPublished:false};let isNav=c==='navigation';$('#work').innerHTML=`<div class="panel"><div class="row"><button class="btn ghost" id="back">← Quay lại</button><h2>${id?'Chỉnh sửa':'Thêm mới'}</h2></div><form id="edit"><div class="split"><div class="field"><label>${isNav?'Nhãn':'Tiêu đề'}</label><input name="${isNav?'label':'title'}" value="${esc(isNav?x.label:x.title)}"></div><div class="field"><label>${isNav?'URL':'Slug'}</label><input name="${isNav?'url':'slug'}" value="${esc(isNav?x.url:x.slug)}"></div></div>${isNav?'':`<div class="field"><label>Mô tả ngắn</label><textarea name="summary" rows="3">${esc(x.summary||'')}</textarea></div><div class="field"><label>Nội dung</label><textarea name="content" rows="12">${esc(x.content||'')}</textarea></div><div class="field"><label>Trạng thái</label><select name="status"><option value="draft">Nháp</option><option value="published" ${x.status==='published'?'selected':''}>Công khai</option><option value="private" ${x.status==='private'?'selected':''}>Riêng tư</option></select></div>`}<button class="btn">Lưu</button> <button type="button" class="btn ghost" id="del">Xóa</button><div id="msg"></div></form></div>`;$('#back').onclick=()=>collectionUI(c);$('#edit').onsubmit=async e=>{e.preventDefault();let d={...x,...Object.fromEntries(new FormData(e.currentTarget))};if(!isNav)d.isPublished=d.status==='published';let r=await fetch('/api/cms',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({collection:c,id:d.id,data:d})}),j=await r.json();$('#msg').innerHTML=`<div class="notice ${r.ok?'':'danger'}">${r.ok?'Đã lưu và cập nhật website.':esc(j.error)}</div>`};$('#del').onclick=async()=>{if(!confirm('Xóa mục này?'))return;await fetch(`/api/cms?collection=${c}&id=${encodeURIComponent(x.id)}`,{method:'DELETE'});collectionUI(c)}}
async function themeUI(){let x=await api('theme_config','main')||defaults.theme_config[0];$('#work').innerHTML=`<div class="panel"><h2>Giao diện</h2><p class="muted">Đổi nhận diện toàn website tại đây.</p><form id="theme"><div class="split">${[['primary','Màu chính'],['accent','Màu nhấn'],['background','Nền'],['surface','Bề mặt'],['text','Chữ'],['mutedText','Chữ phụ']].map(([k,l])=>`<div class="field"><label>${l}</label><input class="color" type="color" name="${k}" value="${esc(x[k])}"></div>`).join('')}</div><div class="split"><div class="field"><label>Bo góc</label><input type="number" name="radius" value="${x.radius||22}"></div><div class="field"><label>Độ rộng nội dung</label><input type="number" name="containerWidth" value="${x.containerWidth||1180}"></div></div><button class="btn">Publish theme</button><div id="msg"></div></form></div>`;$('#theme').onsubmit=async e=>{e.preventDefault();let d={...x,...Object.fromEntries(new FormData(e.currentTarget)),id:'main'};d.radius=+d.radius;d.containerWidth=+d.containerWidth;let r=await fetch('/api/cms',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({collection:'theme_config',id:'main',data:d})});$('#msg').innerHTML=`<div class="notice">${r.ok?'Đã cập nhật giao diện.':'Không thể lưu.'}</div>`}}
async function mediaUI(){let items=[];try{let r=await fetch('/api/media');if(r.ok)items=(await r.json()).items||[]}catch{}$('#work').innerHTML=`<div class="panel"><h2>Media Library</h2><form id="up"><input type="file" name="file" required> <button class="btn">Upload vào R2</button></form><div id="msg"></div></div><div class="panel"><div class="grid">${items.map(x=>`<div class="card" style="grid-column:span 4"><b>${esc(x.name||x.key)}</b><p>${esc(x.key||'')}</p></div>`).join('')}</div></div>`;$('#up').onsubmit=async e=>{e.preventDefault();let r=await fetch('/api/media/upload',{method:'POST',body:new FormData(e.currentTarget)}),j=await r.json();$('#msg').innerHTML=`<div class="notice ${r.ok?'':'danger'}">${r.ok?'Upload thành công.':esc(j.error)}</div>`;if(r.ok)setTimeout(mediaUI,500)}}
render();
